// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX3} from "../src/MultiplicatorX3.sol";

contract InvMutTest is Test {
    MultiplicatorX3 c;
    address owner;

    function setUp() public {
        owner = address(0xA11CE);
        vm.prank(owner);
        c = new MultiplicatorX3();
    }

    function testFuzz_property(uint256 amount, bytes memory data) public {
        vm.assume(data.length <= 1000);
        amount = bound(amount, 1, 100 ether);
        Reverter target = new Reverter();
        vm.deal(owner, amount);
        vm.prank(owner);
        bool ok;
        try c.Command{value: amount}(address(target), data) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok && address(c).balance == amount);
    }
}

contract Reverter {
    fallback() external payable {
        revert();
    }
}
